#include <string>

class Plant {
public:
    explicit Plant(std::string label) : label_(label) {}

    void rename(const std::string& newLabel) {
        label_ = newLabel;
    }

    const std::string& label() const {
        return label_;
    }

private:
    std::string label_;
};

class GardenDisplay {
public:
    GardenDisplay() : focused_(nullptr) {}

    void highlight(Plant& plant) {
        focused_ = &plant;
    }

    bool hasFocus() const {
        return focused_ != nullptr;
    }

    std::string focusedLabel() const {
        return focused_ == nullptr ? "No plant selected" : focused_->label();
    }

private:
    Plant* focused_;
};
